solution.solution.cpp:
#include <string>

// The hexadecimal digits of value, in capitals, with no prefix and no leading zeros.
std::string toHex(unsigned int value)
{
    const std::string digits{ "0123456789ABCDEF" };
    if (value == 0) return "0";

    std::string text{};
    while (value > 0)
    {
        text.insert(text.begin(), digits[value % 16]);   // the lowest four bits are the last digit
        value /= 16;                                     // then drop those four bits
    }
    return text;
}

unitTests:
TEST("zero") { CHECK_EQ(toHex(0), "0"); }
TEST("one digit") { CHECK_EQ(toHex(9), "9"); CHECK_EQ(toHex(10), "A"); CHECK_EQ(toHex(15), "F"); }
TEST("a byte") { CHECK_EQ(toHex(16), "10"); CHECK_EQ(toHex(200), "C8"); CHECK_EQ(toHex(255), "FF"); }
TEST("past a byte") { CHECK_EQ(toHex(256), "100"); CHECK_EQ(toHex(4096), "1000"); CHECK_EQ(toHex(48879), "BEEF"); }
TEST("the largest 32-bit value") { CHECK_EQ(toHex(4294967295u), "FFFFFFFF"); }

